private const val ALIAS = "cle_notes"

fun cleSecrete(): SecretKey {
    val magasin = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
    (magasin.getKey(ALIAS, null) as? SecretKey)?.let { return it }

    val generateur = KeyGenerator.getInstance(
        KeyProperties.KEY_ALGORITHM_AES,
        "AndroidKeyStore",
    )
    generateur.init(
        KeyGenParameterSpec.Builder(
            ALIAS,
            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT,
        )
            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
            .setKeySize(256)
            .build()
    )
    return generateur.generateKey()
}

class Chiffre(val iv: ByteArray, val donnees: ByteArray)

fun chiffrer(texte: String, cle: SecretKey): Chiffre {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.ENCRYPT_MODE, cle)
    return Chiffre(cipher.iv, cipher.doFinal(texte.toByteArray()))
}

fun dechiffrer(chiffre: Chiffre, cle: SecretKey): String {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.DECRYPT_MODE, cle, GCMParameterSpec(128, chiffre.iv))
    return String(cipher.doFinal(chiffre.donnees))
}

