import javax.crypto.AEADBadTagException
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

fun chiffrer(texte: String, cle: SecretKey): Pair<ByteArray, ByteArray> {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.ENCRYPT_MODE, cle)
    return cipher.iv to cipher.doFinal(texte.toByteArray())
}

fun dechiffrer(iv: ByteArray, donnees: ByteArray, cle: SecretKey): String {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.DECRYPT_MODE, cle, GCMParameterSpec(128, iv))
    return String(cipher.doFinal(donnees))
}

fun main() {
    val cle = KeyGenerator.getInstance("AES").apply { init(256) }.generateKey()

    val (iv, donnees) = chiffrer("Le grimoire", cle)
    println(dechiffrer(iv, donnees, cle))

    val (autreIv, _) = chiffrer("Le grimoire", cle)
    println("Même IV ? ${iv.contentEquals(autreIv)}")

    donnees[0] = (donnees[0].toInt() xor 1).toByte()
    try {
        dechiffrer(iv, donnees, cle)
    } catch (e: AEADBadTagException) {
        println("Modification détectée")
    }
}

import java.security.MessageDigest

fun empreinte(texte: String): String =
    MessageDigest.getInstance("SHA-256")
        .digest(texte.toByteArray())
        .joinToString("") { "%02x".format(it) }

fun main() {
    println(empreinte("Druide"))
    println(empreinte("Druide").length)
    println(empreinte("Druide") == empreinte("druide"))
}

