import java.io.File

fun cheminSur(dossier: File, nom: String): File? {
    val cible = File(dossier, nom).canonicalFile
    return if (cible.path.startsWith(dossier.canonicalPath + File.separator)) cible else null
}

fun main() {
    val dossier = File("/data/app/fichiers")
    println(cheminSur(dossier, "photo.png") != null)
    println(cheminSur(dossier, "../../secret.txt") != null)
}

