fun adresseAutorisee(url: String): Boolean {
    val autorisees = setOf("exemple.com", "www.exemple.com")
    val hote = Regex("^https://([^/:?#]+)").find(url)?.groupValues?.get(1)
    return hote != null && hote in autorisees
}

fun main() {
    println(adresseAutorisee("https://exemple.com/page"))
    println(adresseAutorisee("http://exemple.com/page"))
    println(adresseAutorisee("https://exemple.com.piege.net/"))
    println(adresseAutorisee("https://piege.net/exemple.com"))
}

